/// Sends a single, new order into the exchange. A range of order types, Time-In-Force (TIF) settings and order flags can be specified. For triggered order types (`stop-loss`, `take-profit`, `trailing-stop`), `triggers` carries the price-tracking and trigger-threshold parameters. For One-Triggers-Other (OTO) orders, `conditional` carries the parameters for a secondary close order attached to the primary order.
#[derive(Clone)]
pub struct AddOrder {
    core: Arc<dyn CommandEndpoint>,
}

impl AddOrder {
    pub fn new(core: Arc<dyn CommandEndpoint>) -> Self {
        Self { core }
    }

    /// Sends a single, new order into the exchange. A range of order types, Time-In-Force (TIF) settings and order flags can be specified. For triggered order types (`stop-loss`, `take-profit`, `trailing-stop`), `triggers` carries the price-tracking and trigger-threshold parameters. For One-Triggers-Other (OTO) orders, `conditional` carries the parameters for a secondary close order attached to the primary order.
    ///
    /// See <https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/add_order>.
    pub async fn add_order(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<AddOrderResult> {
        let raw = self.add_order_raw(request, options).await?;
        decode(raw)
    }

    /// `add_order` without validation: the wire body as it came.
    pub async fn add_order_raw(
        &self,
        request: Request,
        options: CallOptions,
    ) -> Result<serde_json::Value> {
        let call = CommandCall {
            path: "add_order",
            request: Some(dump(&request)?),
            meta: &(),
            options,
        };
        self.core.request(call).await
    }
}
